package ec.ucsg.analytics.infrastructure.mail;

/**
 * Íconos pequeños (PNG, 20×20 @2x) embebidos como data-URI en base64, usados
 * en las plantillas HTML de {@link EmailNotificationService}.
 *
 * Antes esto eran emoji (📅 📍 🔔 …) puestos directo en el texto. El problema:
 * el glifo de color que renderiza cada emoji depende de la fuente del cliente
 * de correo — en Gmail/Outlook a veces se ve como un cuadro vacío ("tofu") en
 * vez del ícono, según la plataforma. Un <img> con los bytes ya incrustados
 * se ve idéntico en cualquier cliente, sin depender de fuentes de emoji ni de
 * una petición de red adicional (por eso van embebidos, no como URL externa).
 *
 * Generados desde los mismos SVG de lucide-react que usa el frontend (misma
 * familia visual en toda la app, incluyendo el correo) — trazo 2.25, 24×24,
 * renderizados a 40×40px y exportados a PNG con sharp.
 *
 * Sufijo _WHITE  → para texto sobre fondo crimson (encabezados, botón CTA).
 * Sufijo _CRIMSON → para texto sobre fondo claro (la caja de fecha/ubicación).
 */
final class EmailIcons {

    private EmailIcons() {}

    public static final String CALENDAR_WHITE = "data:image/png;base64,";
    public static final String CLOCK_WHITE = "data:image/png;base64,";
    public static final String CHECK_WHITE = "data:image/png;base64,";
    public static final String PARTY_WHITE = "data:image/png;base64,";
    public static final String PENCIL_WHITE = "data:image/png;base64,";
    public static final String XCIRCLE_WHITE = "data:image/png;base64,";
    public static final String BELL_WHITE = "data:image/png;base64,";
    public static final String CALENDAR_CRIMSON = "data:image/png;base64,";
    public static final String MAPPIN_CRIMSON = "data:image/png;base64,";
    public static final String CLOCK_CRIMSON = "data:image/png;base64,";
}
